// APP-04: "bought together" rules mapped to demo product codes.
// Pure functions only; the rule file is generated by analysis/app04-association-rules/mine-rules.mjs.
// Candidate selection, store/ad placement and saving selections belong to APP-05 / APP-13.

export type RuleOrigin = "initial" | "analysis";
export type AssociationRule = {
  id: string; origin: RuleOrigin; from: string; to: string; reason: string;
  confidence?: number; lift?: number; support?: number; testLift?: number;
};
export type AssociationRuleSet = { version: number; rules: AssociationRule[]; initialRules: AssociationRule[] };
export type RelatedCandidate = {
  code: string; ruleId: string; origin: RuleOrigin; reason: string; triggeredBy: string; score: number; ruleVersion: number;
};
export type RelatedOptions = {
  limit?: number;
  // confidence: likely to be bought (APP-05). lift: specific to the trigger, i.e. less obvious (APP-13).
  rankBy?: "confidence" | "lift";
  origins?: RuleOrigin[];
  exclude?: Iterable<string>;
};

/**
 * Candidates related to the products in the cart (codes), deterministic for the same input and rule version.
 * Initial (curated) rules come first because they encode the demo/store intent and work without data;
 * analysis rules follow, ordered by the chosen metric. Products already in the cart or excluded are skipped.
 */
export function relatedProducts(ruleSet: AssociationRuleSet, cartCodes: Iterable<string>, options: RelatedOptions = {}): RelatedCandidate[] {
  const cart = new Set(cartCodes);
  const excluded = new Set([...cart, ...(options.exclude ?? [])]);
  const origins = options.origins ?? ["initial", "analysis"];
  const metric = options.rankBy ?? "confidence";
  const limit = options.limit ?? 5;
  const best = new Map<string, RelatedCandidate>();
  const all = [...ruleSet.initialRules.map(rule => ({ ...rule, origin: "initial" as const })), ...ruleSet.rules];
  for (const rule of all) {
    if (!origins.includes(rule.origin) || !cart.has(rule.from) || excluded.has(rule.to)) continue;
    const score = rule.origin === "initial" ? Number.POSITIVE_INFINITY : rule[metric] ?? 0;
    const candidate: RelatedCandidate = { code: rule.to, ruleId: rule.id, origin: rule.origin, reason: rule.reason,
      triggeredBy: rule.from, score, ruleVersion: ruleSet.version };
    const previous = best.get(rule.to);
    if (!previous || compare(candidate, previous, origins) < 0) best.set(rule.to, candidate);
  }
  return [...best.values()].sort((a, b) => compare(a, b, origins)).slice(0, limit);
}

function compare(a: RelatedCandidate, b: RelatedCandidate, origins: RuleOrigin[]) {
  return origins.indexOf(a.origin) - origins.indexOf(b.origin) || b.score - a.score
    || a.code.localeCompare(b.code) || a.ruleId.localeCompare(b.ruleId);
}
